(window.GROUP_QUIZZES=window.GROUP_QUIZZES||{})["clinical-medicine-and-surgery-i-exam-3-external-middle-ear-quiz"]={"title":"External and Middle Ear Quiz 1 — CMS I Exam 3","category":"Clinical Medicine and Surgery I","exam":"Exam 3","sem":"fall-2026","questions":[{"q":"Which ossicle does otosclerosis affect?","choices":["The incus","The cochlea","The tympanic membrane","The stapes"],"answer":3,"exp":"Correct — bony overgrowth eventually fixes it. — Disorders External and Middle Ear 9-2026.pptx, Slide 65"},{"q":"How is acute otitis media diagnosed?","choices":["By audiometry","By blood cultures","Clinically","By computed tomography of the temporal bone"],"answer":2,"exp":"Correct. Tympanometry is optional and imaging has no routine role. — Disorders External and Middle Ear 9-2026.pptx, Slide 16"},{"q":"What confirms necrotizing external otitis?","choices":["Audiometry showing conductive loss","Tympanometry","Imaging showing infection in the bony structures","A canal swab growing Pseudomonas"],"answer":2,"exp":"Correct — computed tomography or magnetic resonance imaging. — Disorders External and Middle Ear 9-2026.pptx, Slide 61"},{"q":"At what age does acute otitis media peak?","choices":["Around forty years","Around two years","Around six months","Around twelve years"],"answer":1,"exp":"Correct. It is the commonest paediatric ear disease at that age. — Disorders External and Middle Ear 9-2026.pptx, Slide 12"},{"q":"Into how many clinical divisions is the ear separated?","choices":["Four","Five","Three","Two"],"answer":2,"exp":"Correct. External, middle and inner. — Disorders External and Middle Ear 9-2026.pptx, Slide 4"},{"q":"Which otoscopic appearance is described as resembling wet newspaper?","choices":["Aspergillus infection","Candida infection","Pseudomonas infection","Cholesteatoma"],"answer":0,"exp":"Correct — visible spores and filaments. — Disorders External and Middle Ear 9-2026.pptx, Slide 63"},{"q":"Which everyday item is named as a risk factor for otitis externa through canal occlusion?","choices":["Reading glasses","A pillow","A face mask","Hearing aids"],"answer":3,"exp":"Correct, along with headphones. — Disorders External and Middle Ear 9-2026.pptx, Slide 56"},{"q":"Which symptom pattern fits cerumen impaction?","choices":["Bloody discharge","Itching, fullness and hearing loss","Vertigo and vomiting","Facial weakness"],"answer":1,"exp":"Correct — or it may be entirely asymptomatic. — Disorders External and Middle Ear 9-2026.pptx, Slide 28"},{"q":"Which class of antibiotic is required for necrotizing external otitis?","choices":["Topical steroid alone","Antipseudomonal","Antifungal","Antiviral"],"answer":1,"exp":"Correct — ciprofloxacin is the named example. — Disorders External and Middle Ear 9-2026.pptx, Slide 61"},{"q":"Which measure is recommended for a frequent flyer with repeated ear barotrauma?","choices":["A hearing aid","Tympanostomy tubes","Permanent avoidance of all flying","Routine myringotomy before every flight"],"answer":1,"exp":"Correct — considered when episodes recur despite ordinary measures. — Disorders External and Middle Ear 9-2026.pptx, Slide 25"},{"q":"What is the commonest cause of cerumen impaction?","choices":["Swimming","A narrow ear canal alone","Attempts at cleaning the ear","Excessive wax production alone"],"answer":2,"exp":"Correct. Cleaning pushes wax deeper; the canal is normally self-cleansing. — Disorders External and Middle Ear 9-2026.pptx, Slide 27"},{"q":"How is a marginal perforation distinguished from a central one?","choices":["A marginal perforation involves the drum margin","A marginal perforation always bleeds","A marginal perforation causes vertigo","A marginal perforation is always traumatic"],"answer":0,"exp":"Correct; a central one does not reach it. — Disorders External and Middle Ear 9-2026.pptx, Slide 46"},{"q":"Which exposure is the leading risk factor for otitis externa?","choices":["Air travel","Cold water diving","High altitude living","Moisture and swimming"],"answer":3,"exp":"Correct. — Disorders External and Middle Ear 9-2026.pptx, Slide 56"},{"q":"Within what period should an auricular haematoma be drained?","choices":["Within thirty days","Drainage is never required","Within seven days","Within one hour"],"answer":2,"exp":"Correct. After that, granulation tissue makes drainage much harder. — Disorders External and Middle Ear 9-2026.pptx, Slide 41"},{"q":"Which cranial nerve finding may accompany necrotizing external otitis?","choices":["Double vision","Tongue deviation","Loss of the gag reflex","Facial nerve weakness"],"answer":3,"exp":"Correct. — Disorders External and Middle Ear 9-2026.pptx, Slide 61"},{"q":"Which set of symptoms after barotrauma indicates that the inner ear has been involved?","choices":["Facial weakness and severe pain","Vertigo, tinnitus and sensorineural hearing loss","Fever, otalgia and purulent discharge","Itching and canal tenderness"],"answer":1,"exp":"Correct. Rupture of the round or oval window adds these, with nausea and vomiting. — Disorders External and Middle Ear 9-2026.pptx, Slide 24"},{"q":"What is by far the commonest cause of acute otitis media overall?","choices":["Streptococcus pneumoniae","Haemophilus influenzae","Pseudomonas aeruginosa","A virus"],"answer":3,"exp":"Correct. Most episodes are viral, which is why most resolve without antibiotics. — Disorders External and Middle Ear 9-2026.pptx, Slide 17"},{"q":"What establishes the diagnosis of carcinoma of the ear canal?","choices":["Biopsy","Computed tomography","Culture of the discharge","Tympanometry"],"answer":0,"exp":"Correct. — Disorders External and Middle Ear 9-2026.pptx, Slide 71"},{"q":"What proportion of people experience otitis externa in their lifetime?","choices":["About ten per cent","About thirty per cent","About half","Over ninety per cent"],"answer":0,"exp":"Correct. — Disorders External and Middle Ear 9-2026.pptx, Slide 54"},{"q":"What causes a keloid of the ear?","choices":["Trauma, classically ear piercing","Cold water exposure","Chronic infection","Loud noise"],"answer":0,"exp":"Correct. — Disorders External and Middle Ear 9-2026.pptx, Slide 69"},{"q":"What is used when the ear canal is too swollen for drops to reach the skin?","choices":["A tympanostomy tube","A pressure dressing","A cotton plug","An ear wick"],"answer":3,"exp":"Correct. — Disorders External and Middle Ear 9-2026.pptx, Slide 59"},{"q":"Why do ear keloids require close follow-up after treatment?","choices":["Recurrence is common","They become malignant","They cause hearing loss","They cause facial paralysis"],"answer":0,"exp":"Correct. — Disorders External and Middle Ear 9-2026.pptx, Slide 70"},{"q":"Which condition is a risk factor for developing a cholesteatoma?","choices":["Eustachian tube dysfunction","Presbycusis","Noise exposure","Otosclerosis"],"answer":0,"exp":"Correct, along with chronic middle ear inflammation. — Disorders External and Middle Ear 9-2026.pptx, Slide 32"},{"q":"Forced exhalation against resistance carries which specific caution?","choices":["Avoid it in the morning","Avoid it during active nasal discharge","Avoid it in anyone over sixty-five","Avoid it if the patient wears hearing aids"],"answer":1,"exp":"Correct. It can push infected secretions into the middle ear and cause acute otitis media. — Disorders External and Middle Ear 9-2026.pptx, Slide 10"},{"q":"Which procedure gives instant relief in severe barotrauma with an intact drum?","choices":["Tympanoplasty","Myringotomy","Mastoidectomy","Stapedectomy"],"answer":1,"exp":"Correct, reserved for severe pain and hearing loss. — Disorders External and Middle Ear 9-2026.pptx, Slide 25"},{"q":"What colour is a normal tympanic membrane?","choices":["Bright red","Chalky white","Deep blue","Pearly grey"],"answer":3,"exp":"Correct. Loss of that appearance is the first sign something lies behind it. — Disorders External and Middle Ear 9-2026.pptx, Slide 8"},{"q":"Which two activities are named as causing ear barotrauma?","choices":["Weightlifting and running","Using headphones and hearing aids","Air travel and underwater diving","Swimming and showering"],"answer":2,"exp":"Correct, along with any rapid altitude change. — Disorders External and Middle Ear 9-2026.pptx, Slide 22"},{"q":"Which measure follows drainage to prevent re-accumulation?","choices":["Tympanostomy tube placement","Ear splinting","A course of antifungal drops","Weekly audiometry"],"answer":1,"exp":"Correct — bolsters, plaster moulds, silicone putty or thermoplastic splints. — Disorders External and Middle Ear 9-2026.pptx, Slide 41"},{"q":"What is the management of chronic otitis media in primary care?","choices":["Referral to an ear, nose and throat specialist","Irrigation of the canal with warm water","Observation for one year","Tympanometry every three months"],"answer":0,"exp":"Correct. — Disorders External and Middle Ear 9-2026.pptx, Slide 20"},{"q":"Which perforations require surgical reconstruction?","choices":["Only bilateral ones","Only painful ones","Large ones, or ones present a long time","Every perforation, without exception"],"answer":2,"exp":"Correct. — Disorders External and Middle Ear 9-2026.pptx, Slide 47"}]};
